// Package archgold selects a frozen bit-exactness golden for the architecture a test runs on.
//
// The repo's *BitIdentical tests freeze an FNV digest of a kernel's output bits. That is the right
// gate — the claim they defend is that an optimization reorders nothing, and a tolerance test would
// pass a reordering that changes the last ulp. But a single frozen constant CANNOT be portable,
// for two independent reasons, both measured on 2026-08-16 rather than inferred:
//
//  1. Go's math.Sin/math.Cos are not bit-identical across GOARCH. Sweeping the inputs these tests
//     build their fixtures from, 41 of 2048 values differ by one ulp (math.Cos(84) ends e523 on
//     arm64 and e522 on amd64). Where a fixture is built from a transcendental, the INPUTS already
//     differ and everything downstream follows. Spot-checking individual values is not enough to
//     rule this out — Sin(129) and Cos(451) agree exactly, and the sweep still diverges.
//
//  2. Floating-point contraction differs. arm64 fuses `v -= a*b` into FNMSUB; amd64 at the default
//     GOAMD64=v1 does not, and one rounding step per term is enough to change the digest. The
//     clincher: with exact dyadic fixtures, the only shape whose digest matched across arches was
//     the one small enough that the unrolled loop never ran.
//
// Cause 2 cannot be fixed by choosing better fixtures, so the goldens are per-architecture. Each
// arch still gets a full bit-exact assertion — nothing is weakened to a tolerance — and a
// reordering on either one is still caught.
//
// The amd64 values are trustworthy from an Apple-silicon dev box: `GOARCH=amd64 go test` runs under
// Rosetta 2 and reproduces CI exactly. TestQRVJPIsBitIdentical reports the same digests under
// Rosetta as on GitHub's ubuntu-latest and windows-latest runners, so one golden per arch class is
// sufficient and can be regenerated locally.
package archgold

import "runtime"

// Reason explains a skip on an architecture with no recorded goldens. Pass it to t.Skip.
const Reason = "no bit-exactness goldens recorded for GOARCH=" + runtime.GOARCH +
	" (digests are architecture-specific: FP contraction and math.Sin/Cos both differ); " +
	"record them with: GOARCH=<arch> go test -run <TestName> ./<pkg>/"

// Supported reports whether goldens exist for the current architecture. Tests that freeze digests
// must skip when it is false — asserting another architecture's constants would fail for a reason
// that says nothing about the code under test.
func Supported() bool { return runtime.GOARCH == "arm64" || runtime.GOARCH == "amd64" }

// Pick returns the golden for the current architecture. On an architecture without goldens it
// returns the arm64 value, which is harmless because Supported gates the assertion; keeping it
// total means a table literal stays a plain expression.
func Pick(arm64, amd64 uint64) uint64 {
	if runtime.GOARCH == "amd64" {
		return amd64
	}
	return arm64
}

// PickSIMD extends Pick for tests whose output intentionally changes when the
// experimental SIMD implementation replaces a scalar transcendental path.
func PickSIMD(arm64, amd64, arm64SIMD, amd64SIMD uint64) uint64 {
	if simdExperiment {
		if runtime.GOARCH == "amd64" {
			return amd64SIMD
		}
		return arm64SIMD
	}
	return Pick(arm64, amd64)
}
//go:build arm64 && goexperiment.simd

package cpu

import (
	"math"
	"testing"
)

func TestVsiluF64Arm64Accuracy(t *testing.T) {
	const n = 1<<18 + 1 // odd: vector body plus scalar tail
	src := make([]float64, n)
	for i := range src {
		src[i] = -80 + 160*float64(i)/float64(n-1)
	}
	dst := make([]float64, n)
	vsiluF64(dst, src)

	var maxRel float64
	for i, x := range src {
		want := x / (1 + math.Exp(-x))
		rel := math.Abs(dst[i]-want) / math.Max(1, math.Abs(want))
		if rel > maxRel {
			maxRel = rel
		}
	}
	t.Logf("ARM64 NEON F64 SiLU max relative error %.3e over %d values", maxRel, n)
	if maxRel > 1e-13 {
		t.Fatalf("max relative error %.3e exceeds 1e-13", maxRel)
	}
}

func TestVsiluF64Arm64VectorTailBitIdentity(t *testing.T) {
	for x := -80.0; x <= 80.0; x += 0.00031 {
		body := []float64{0, 0}
		vsiluF64(body, []float64{x, x})
		tail := siluF64poly(x)
		if math.Float64bits(body[0]) != math.Float64bits(tail) ||
			math.Float64bits(body[1]) != math.Float64bits(tail) {
			t.Fatalf("x=%g: vector=(%#x,%#x) tail=%#x", x,
				math.Float64bits(body[0]), math.Float64bits(body[1]), math.Float64bits(tail))
		}
	}
}

func TestVsiluF64Arm64Edges(t *testing.T) {
	negZero := math.Copysign(0, -1)
	edges := []float64{0, negZero, 1, -1, 80, -80, math.Inf(1), math.Inf(-1), math.NaN()}
	body := make([]float64, len(edges)) // odd length also exercises the scalar tail
	vsiluF64(body, edges)
	for i, x := range edges {
		want := siluF64poly(x)
		if math.IsNaN(want) {
			if !math.IsNaN(body[i]) {
				t.Errorf("x=%v: got %v, want NaN", x, body[i])
			}
			continue
		}
		if math.Float64bits(body[i]) != math.Float64bits(want) {
			t.Errorf("x=%v: vector=%v (%#x), scalar=%v (%#x)", x, body[i],
				math.Float64bits(body[i]), want, math.Float64bits(want))
		}
	}
	if !math.Signbit(body[1]) || body[1] != 0 {
		t.Errorf("SiLU(-0)=%v, want negative zero", body[1])
	}
	if !math.IsInf(body[6], 1) {
		t.Errorf("SiLU(+Inf)=%v, want +Inf", body[6])
	}
	if !math.IsNaN(body[7]) {
		t.Errorf("SiLU(-Inf)=%v, want NaN like scalar x/(1+exp(-x))", body[7])
	}
}

// siluF64scalarRef is byte-for-byte the loop the non-SIMD build runs for OpSiLU/F64
// (elementwise.go's fallback). It exists so the NEON lane can be A/B'd against the
// path it replaces inside ONE binary, with no build-tag juggling to confound the
// measurement.
func siluF64scalarRef(dst, src []float64) {
	for i, x := range src {
		dst[i] = x / (1 + math.Exp(-x))
	}
}

// BenchmarkVsiluF64Arm64 measures the NEON lane against the scalar fallback it
// replaces, on the SwiGLU-shaped length the FFN gate actually issues.
func BenchmarkVsiluF64Arm64(b *testing.B) {
	const n = 256 * 1408 // [256,1408] f64, the T985 SwiGLU FFN shape
	src := make([]float64, n)
	for i := range src {
		src[i] = -8 + 16*float64(i)/float64(n-1)
	}
	dst := make([]float64, n)
	b.Run("neon", func(b *testing.B) {
		b.SetBytes(int64(n * 8))
		for b.Loop() {
			vsiluF64(dst, src)
		}
	})
	b.Run("scalar", func(b *testing.B) {
		b.SetBytes(int64(n * 8))
		for b.Loop() {
			siluF64scalarRef(dst, src)
		}
	})
}
//go:build amd64 && goexperiment.simd

package cpu

import (
	"math"
	"testing"

	"simd/archsimd"
)

// TestExpF64x4Accuracy checks expF64x4 vs math.Exp over the SiLU arg range (x ≤ 0)
// to sub-ulp — the accuracy the Llama f64 golden (1e-12) relies on.
func TestExpF64x4Accuracy(t *testing.T) {
	var maxUlp, maxRel float64
	for x := -40.0; x <= 0.0; x += 0.0003 {
		in := []float64{x, x, x, x}
		got := make([]float64, 4)
		// route through vsiluF64's exp by calling expF64x4 directly via a tiny shim.
		v := loadExp(in)
		copy(got, v)
		want := math.Exp(x)
		if want == 0 {
			continue
		}
		rel := math.Abs(got[0]-want) / want
		if rel > maxRel {
			maxRel = rel
		}
		ulp := math.Abs(got[0]-want) / ulpF64(want)
		if ulp > maxUlp {
			maxUlp = ulp
		}
	}
	t.Logf("expF64x4 vs math.Exp over [-40,0]: maxRel=%.3e maxUlp=%.2f", maxRel, maxUlp)
	if maxRel > 1e-14 {
		t.Fatalf("expF64x4 maxRel=%.3e exceeds 1e-14", maxRel)
	}
}

// TestVsiluF64Accuracy checks vsiluF64 vs the scalar x/(1+exp(-x)) reference.
func TestVsiluF64Accuracy(t *testing.T) {
	n := 4096
	src := make([]float64, n)
	for i := range src {
		src[i] = -80 + 160*float64(i)/float64(n) // [-80, 80]
	}
	dst := make([]float64, n)
	vsiluF64(dst, src)
	var maxRel float64
	for i, x := range src {
		want := x / (1 + math.Exp(-x))
		den := math.Max(1, math.Abs(want))
		rel := math.Abs(dst[i]-want) / den
		if rel > maxRel {
			maxRel = rel
		}
	}
	t.Logf("vsiluF64 vs scalar over [-80,80] n=%d: maxRel=%.3e", n, maxRel)
	if maxRel > 1e-13 {
		t.Fatalf("vsiluF64 maxRel=%.3e exceeds 1e-13", maxRel)
	}
}

func ulpF64(x float64) float64 {
	return math.Abs(math.Nextafter(x, math.Inf(1)) - x)
}

// TestExpF64polyMatchesVector asserts the scalar tail primitive is BIT-EXACT to
// the SIMD lane — the property that keeps decode==forward byte-exact.
func TestExpF64polyMatchesVector(t *testing.T) {
	mism := 0
	for x := -80.0; x <= 0.0; x += 0.00017 {
		v := loadExp([]float64{x, x, x, x})
		s := expF64poly(x)
		if math.Float64bits(v[0]) != math.Float64bits(s) {
			if mism < 5 {
				t.Errorf("x=%v: vector %v (%#x) != scalar %v (%#x)", x, v[0], math.Float64bits(v[0]), s, math.Float64bits(s))
			}
			mism++
		}
	}
	if mism > 0 {
		t.Fatalf("%d bit-mismatches between expF64x4 and expF64poly", mism)
	}
}

func loadExp(in []float64) []float64 {
	x := archsimd.LoadFloat64x4(in)
	out := make([]float64, 4)
	expF64x4(x).Store(out)
	return out
}
